SELECT cs.cs_sold_date_sk, w.w_warehouse_name, cs.cs_quantity, cs.cs_sales_price, cs.cs_quantity * cs.cs_sales_price AS total_sales, CASE WHEN cs.cs_quantity > 53 THEN cs.cs_sales_price * 1.1 ELSE cs.cs_sales_price * 0.9 END AS price_adjusted, (cs.cs_ext_sales_price - cs.cs_ext_discount_amt) AS net_sales, CASE WHEN w.w_gmt_offset > -5.00 THEN 'East' ELSE 'West' END AS region_category FROM catalog_sales cs JOIN warehouse w ON cs.cs_warehouse_sk = w.w_warehouse_sk WHERE cs.cs_sold_date_sk >= 2450831 AND cs.cs_sold_date_sk <= 2450833 AND w.w_state = 'MN'
